"""Dos pruebas adicionales sobre alinear periodos y evitar comparaciones invalidas."""
from unittest.mock import patch
import pytest
from fastmcp.exceptions import ToolError
import server


def ejemplo(codigo, datos, frecuencia="Mensual"):
    return {"codigo": codigo, "frecuencia": frecuencia, "datos": datos,
            "fuente": f"https://estadisticas.bcrp.gob.pe/estadisticas/series/api/{codigo}"}


def test_comparar_series_solo_interseccion():
    a = ejemplo("A", [{"periodo": "2024-01", "valor": 1}, {"periodo": "2024-02", "valor": 2},
                      {"periodo": "2024-03", "valor": 3}, {"periodo": "2024-04", "valor": 4}])
    b = ejemplo("B", [{"periodo": "2024-02", "valor": 6}, {"periodo": "2024-03", "valor": 4},
                      {"periodo": "2024-04", "valor": 2}, {"periodo": "2024-05", "valor": 0}])
    with patch.object(server, "serie", side_effect=[a, b]):
        resultado = server.comparar_series("A", "B", "2024-01", "2024-05")
    assert resultado["n_periodos"] == 3
    assert resultado["desde_real"] == "2024-02"
    assert resultado["correlacion_pearson"] == pytest.approx(-1.0)
    assert len(resultado["fuentes"]) == 2


def test_comparar_series_rechaza_pocos_periodos():
    a = ejemplo("A", [{"periodo": "2024-01", "valor": 1}, {"periodo": "2024-02", "valor": 2}])
    b = ejemplo("B", [{"periodo": "2024-02", "valor": 8}, {"periodo": "2024-03", "valor": 3}])
    with patch.object(server, "serie", side_effect=[a, b]):
        with pytest.raises(ToolError, match="se requieren 3"):
            server.comparar_series("A", "B", "2024-01", "2024-03")
