            continue
        for item in mensaje.get("content") or []:
            if isinstance(item, dict) and item.get("type") == "tool_use":
                entrada = item.get("input") or {}
                if item.get("name") == "Skill":
                    skills.add(str(entrada.get("skill") or entrada.get("name") or "").removeprefix("/"))
